EXPECTED_OLD_HASH='a28531aef25eee8936dc830f2038f7c5d46cc9ef355f19effe28c12461ce667a'
EXPECTED_NEW_HASH='86224241ad1813cbc155683df98c5c7dd4705cebc1d2decfcdcf307360511487'
SOURCE_B64=''
from pathlib import Path
import fcntl,hashlib,json,os,base64,datetime,sys
R=Path('/opt/pureeos-testnet-stall-recovery-20261116-r1');os.umask(0o077)
assert not(R/'PAGINATION_PATCH_STARTED.json').exists()
lock=(R/'native-operation.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
e=json.loads((R/'GUARD_INFLIGHT.json').read_text());assert e['status']in ['PASS_ONE_GUARDED_RECYCLE','PASS_RECONCILED_SAME_OPERATION','ABORTED_BEFORE_NATIVE_STOP_RETRY_AFTER_COOLDOWN']
p=R/'stability_guard.py';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(p)==EXPECTED_OLD_HASH
result={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'old_sha256':EXPECTED_OLD_HASH,'new_sha256':EXPECTED_NEW_HASH,'scope':'Bounded complete native-table pagination only. No node stop/start, timer, signing or chain write. Prior 30 checks plus nine pagination regressions PASS.'}
(R/'PAGINATION_PATCH_STARTED.json').write_text(json.dumps(result,indent=2)+'\n')
backup=R/'stability_guard.pre-pagination.py';assert not backup.exists();backup.write_bytes(p.read_bytes())
tmp=R/'stability_guard.pagination-new.tmp';assert not tmp.exists();tmp.write_bytes(base64.b64decode(SOURCE_B64));assert sha(tmp)==EXPECTED_NEW_HASH;os.replace(tmp,p);fcntl.flock(lock,fcntl.LOCK_UN)
sys.path.insert(0,str(R));import stability_guard as g
rows=g.rows();assert len(rows)==47;assert sum(bool(v['banned'])for v in rows.values())==21
s,i,pids,ro,mem=g.status_context(g.load('GUARD_NODE_MAP.json'));assert s['all_running']and s['head_age']<5 and s['lib_age']<20
result.update(status='PASS_PAGINATION_SOURCE_PATCH_COMPLETE47_ROWS',rows=len(rows),banned=21,head=i['head_block_num'],LIB=i['last_irreversible_block_num'],read_only_context=s)
(R/'PAGINATION_PATCH_RESULT.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
